// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract SocialIdRegistry {
    uint256 public nextId = 1;

    mapping(address => uint256) public idOf;
    mapping(uint256 => address) public ownerOf;
    mapping(uint256 => address) public recoveryOf;

    event Register(uint256 indexed id, address indexed owner, address indexed recovery);
    event Transfer(uint256 indexed id, address indexed from, address indexed to);
    event ChangeRecovery(uint256 indexed id, address indexed recovery);

    function register(address recovery) external returns (uint256 id) {
        require(idOf[msg.sender] == 0, "already registered");

        id = nextId++;
        idOf[msg.sender] = id;
        ownerOf[id] = msg.sender;
        recoveryOf[id] = recovery;

        emit Register(id, msg.sender, recovery);
    }

    function transfer(uint256 id, address to) external {
        require(ownerOf[id] == msg.sender || recoveryOf[id] == msg.sender, "not authorized");
        require(to != address(0), "invalid recipient");
        require(idOf[to] == 0, "recipient registered");

        address from = ownerOf[id];
        idOf[from] = 0;
        idOf[to] = id;
        ownerOf[id] = to;

        emit Transfer(id, from, to);
    }

    function changeRecovery(uint256 id, address recovery) external {
        require(ownerOf[id] == msg.sender, "not owner");
        recoveryOf[id] = recovery;

        emit ChangeRecovery(id, recovery);
    }
}

contracts/SocialKeyRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

interface ISocialIdRegistry {
    function ownerOf(uint256 id) external view returns (address);
}

contract SocialKeyRegistry {
    ISocialIdRegistry public immutable ids;

    mapping(uint256 => mapping(bytes32 => bool)) public keyOf;

    event AddKey(uint256 indexed id, bytes32 indexed key);
    event RemoveKey(uint256 indexed id, bytes32 indexed key);

    constructor(address idRegistry) {
        ids = ISocialIdRegistry(idRegistry);
    }

    function addKey(uint256 id, bytes32 key) external {
        require(ids.ownerOf(id) == msg.sender, "not owner");
        keyOf[id][key] = true;

        emit AddKey(id, key);
    }

    function removeKey(uint256 id, bytes32 key) external {
        require(ids.ownerOf(id) == msg.sender, "not owner");
        keyOf[id][key] = false;

        emit RemoveKey(id, key);
    }
}

contracts/SocialStorageRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

interface IStorageIdRegistry {
    function ownerOf(uint256 id) external view returns (address);
}

contract SocialStorageRegistry {
    IStorageIdRegistry public immutable ids;
    uint256 public unitPrice;
    uint256 public unitSeconds = 365 days;

    mapping(uint256 => uint256) public paidUntil;

    event Rent(uint256 indexed id, uint256 paidUntil);
    event SetUnitPrice(uint256 unitPrice);

    constructor(address idRegistry, uint256 initialUnitPrice) {
        ids = IStorageIdRegistry(idRegistry);
        unitPrice = initialUnitPrice;
    }

    function rent(uint256 id) external payable {
        require(ids.ownerOf(id) == msg.sender, "not owner");
        require(msg.value >= unitPrice, "underpaid");

        uint256 startsAt = paidUntil[id] > block.timestamp ? paidUntil[id] : block.timestamp;
        paidUntil[id] = startsAt + unitSeconds;

        emit Rent(id, paidUntil[id]);
    }
}

